        ["登录账号与离线收货配置不一致。"] = ("The signed-in account differs from the offline receiving configuration.", "La cuenta activa difiere de la configuración de recepción sin conexión."),
        ["还有其他账号或站点的待上传收货，请使用原账号上传后再切换。"] = ("Another account or site has pending receipts. Upload them with the original account before switching.", "Otra cuenta o sitio tiene recepciones pendientes. Súbalas con la cuenta original antes de cambiar."),
        ["缺少收货配置。"] = ("Receiving configuration is missing.", "Falta la configuración de recepción."),
        ["请先上传当前批次，未确认记录不能清空。"] = ("Upload the current batch before clearing the unconfirmed records.", "Suba el lote actual antes de borrar los registros sin confirmar."),
        ["当前登录与本地记录不匹配，请使用原账号和站点。"] = ("Local records belong to a different login. Use the original account and site.", "Los registros locales pertenecen a otra sesión. Use la cuenta y el sitio originales."),
        ["服务器确认不完整，本批记录已保留，请重试。"] = ("Server confirmation is incomplete. The batch was retained. Try again.", "La confirmación del servidor está incompleta. Se conservó el lote. Vuelva a intentarlo."),
        ["服务器响应为空，记录已保留。"] = ("The server response was empty. Records were retained.", "La respuesta del servidor estaba vacía. Se conservaron los registros."),
