    public static string T(string key) => Language == "zh" ? key : Messages.TryGetValue(key, out var text)
        ? Language == "es" ? text.Spanish : text.English : key;
    public static string F(string key, params object?[] values) => string.Format(
        CultureInfo.GetCultureInfo(Language switch { "zh" => "zh-CN", "es" => "es-ES", _ => "en-US" }), T(key), values);
    public static string ReceivingHttpError(int statusCode, string message)
    {
        const string fallback = "请求失败（HTTP {0}），未确认记录已保留。";
        if (string.IsNullOrWhiteSpace(message) || message == string.Format(CultureInfo.InvariantCulture, fallback, statusCode))
            return F(fallback, statusCode);
        if (Language == "zh" || Messages.ContainsKey(message))
            return F("请求失败（HTTP {0}）：{1}", statusCode, T(message));
        return F(fallback, statusCode);
    }
    public static string Error(Exception error) => error switch
    {
        TaskCanceledException => T("上传超时，未确认记录已保留，请重试。"),
        HttpRequestException => T("无法连接服务器，未确认记录已保留。"),
        _ => TranslateError(error.Message)
    };
    public static string TranslateError(string message) => Messages.ContainsKey(message) ? T(message)
        : message.Any(c => c is >= '\u4E00' and <= '\u9FFF') ? T("请求失败，请重试。") : message;
}
